/* SDIO 初始化第一步：先清干净 */
SDIO_DeInit();

/* 再开时钟（AHB 外设，别用 APB2PeriphClockCmd） */
RCC_AHBPeriphClockCmd(RCC_AHBPeriph_SDIO, ENABLE);

/* 之后才能 SetPowerState / Init */
SDIO_SetPowerState(SDIO_PowerState_ON);

SDIO_InitTypeDef SDIO_InitStructure;

SDIO_DeInit();
RCC_AHBPeriphClockCmd(RCC_AHBPeriph_SDIO, ENABLE);
SDIO_SetPowerState(SDIO_PowerState_ON);

/* ---- 阶段一：识别阶段，卡时钟必须 <= 400kHz ---- */
/* HCLK = 72MHz 时 72M/(2*(118+2)) = 300kHz */
SDIO_InitStructure.SDIO_ClockDiv            = 118;
SDIO_InitStructure.SDIO_ClockEdge           = SDIO_ClockEdge_Rising;
SDIO_InitStructure.SDIO_ClockBypass         = SDIO_ClockBypass_Disable;
SDIO_InitStructure.SDIO_ClockPowerSave      = SDIO_ClockPowerSave_Disable;
SDIO_InitStructure.SDIO_BusWide             = SDIO_BusWide_1b;   /* 识别阶段只能用 1 位 */
SDIO_InitStructure.SDIO_HardwareFlowControl = SDIO_HardwareFlowControl_Disable;
SDIO_Init(&SDIO_InitStructure);
SDIO_ClockCmd(ENABLE);

/* 这里发 CMD0 / CMD8 / ACMD41 / CMD2 / CMD3 完成卡的识别 */

/* ---- 阶段二：数据传输阶段，卡时钟 <= 25MHz ---- */
SDIO_ClockCmd(DISABLE);                       /* 改分频前先关时钟 */
SDIO_InitStructure.SDIO_ClockDiv = 1;         /* 72M/(2*(1+2)) = 12MHz，稳妥 */
SDIO_InitStructure.SDIO_BusWide  = SDIO_BusWide_4b;
SDIO_Init(&SDIO_InitStructure);
SDIO_ClockCmd(ENABLE);

SDIO_InitTypeDef SDIO_InitStructure;

SDIO_StructInit(&SDIO_InitStructure);      /* 先填默认值 */
SDIO_InitStructure.SDIO_ClockDiv = 118;    /* 千万别漏：默认 0 会得到 18MHz */
SDIO_InitStructure.SDIO_BusWide  = SDIO_BusWide_1b;
SDIO_Init(&SDIO_InitStructure);

SDIO_Init(&SDIO_InitStructure);
SDIO_ClockCmd(ENABLE);    /* 不开时钟，后面所有 CMD 都收不到响应 */

/* 要改分频时先把时钟关掉 */
SDIO_ClockCmd(DISABLE);
SDIO_InitStructure.SDIO_ClockDiv = 1;
SDIO_Init(&SDIO_InitStructure);
SDIO_ClockCmd(ENABLE);

SDIO_DeInit();
RCC_AHBPeriphClockCmd(RCC_AHBPeriph_SDIO, ENABLE);

/* 给卡上电，必须在 SDIO_Init 之前 */
SDIO_SetPowerState(SDIO_PowerState_ON);

/* 上电后建议延时约 1ms 再发 CMD0（至少 74 个卡时钟） */
Delay_ms(1);

SDIO_Init(&SDIO_InitStructure);
SDIO_ClockCmd(ENABLE);

/* 现在才能发 CMD0 让卡进入 IDLE */

SDIO_SetPowerState(SDIO_PowerState_ON);

/* 自检：确认控制器确实上电了 */
if (SDIO_GetPowerState() != 0x03)
{
  /* 上电失败：检查 SDIO 时钟是否使能、是否刚 DeInit 过 */
}

NVIC_InitTypeDef NVIC_InitStructure;

/* 只开「数据结束 + 错误」类中断，避免 FIFO 类中断刷屏 */
SDIO_ITConfig(SDIO_IT_DATAEND | SDIO_IT_DCRCFAIL | SDIO_IT_DTIMEOUT, ENABLE);

NVIC_InitStructure.NVIC_IRQChannel = SDIO_IRQn;
NVIC_InitStructure.NVIC_IRQChannelPreemptionPriority = 0x03;
NVIC_InitStructure.NVIC_IRQChannelSubPriority = 0x00;
NVIC_InitStructure.NVIC_IRQChannelCmd = ENABLE;
NVIC_Init(&NVIC_InitStructure);

void SDIO_IRQHandler(void)
{
  if (SDIO_GetITStatus(SDIO_IT_DATAEND) != RESET)
  {
    SDIO_ClearITPendingBit(SDIO_IT_DATAEND);
  }
  if (SDIO_GetITStatus(SDIO_IT_DCRCFAIL) != RESET)
  {
    SDIO_ClearITPendingBit(SDIO_IT_DCRCFAIL);   /* CRC 错要处理，否则数据不可信 */
  }
}

DMA_InitTypeDef DMA_InitStructure;

/* SDIO 在 STM32F103 上固定使用 DMA2 通道 4 */
RCC_AHBPeriphClockCmd(RCC_AHBPeriph_DMA2, ENABLE);

DMA_DeInit(DMA2_Channel4);
DMA_InitStructure.DMA_PeripheralBaseAddr = (uint32_t)&SDIO->FIFO;
DMA_InitStructure.DMA_MemoryBaseAddr     = (uint32_t)buffer;
DMA_InitStructure.DMA_DIR                = DMA_DIR_PeripheralSRC;  /* 读卡 */
DMA_InitStructure.DMA_BufferSize         = blockCount * 128;       /* 以 32 位字为单位 */
DMA_InitStructure.DMA_PeripheralInc      = DMA_PeripheralInc_Disable;
DMA_InitStructure.DMA_MemoryInc          = DMA_MemoryInc_Enable;
DMA_InitStructure.DMA_PeripheralDataSize = DMA_PeripheralDataSize_Word;
DMA_InitStructure.DMA_MemoryDataSize     = DMA_MemoryDataSize_Word;
DMA_InitStructure.DMA_Mode               = DMA_Mode_Normal;
DMA_InitStructure.DMA_Priority           = DMA_Priority_High;
DMA_InitStructure.DMA_M2M                = DMA_M2M_Disable;
DMA_Init(DMA2_Channel4, &DMA_InitStructure);

DMA_Cmd(DMA2_Channel4, ENABLE);
SDIO_DMACmd(ENABLE);   /* 打开 SDIO 侧的 DMA 请求 */

/* 再发带数据传输的 CMD（如 CMD17/CMD24） */

SDIO_CmdInitTypeDef SDIO_CmdInitStructure;

/* ---- CMD0：复位卡进入 IDLE，无响应 ---- */
SDIO_CmdStructInit(&SDIO_CmdInitStructure);
SDIO_CmdInitStructure.SDIO_Argument = 0x00;
SDIO_CmdInitStructure.SDIO_CmdIndex = 0;
SDIO_CmdInitStructure.SDIO_Response = SDIO_Response_No;
SDIO_CmdInitStructure.SDIO_Wait     = SDIO_Wait_No;
SDIO_CmdInitStructure.SDIO_CPSM     = SDIO_CPSM_Enable;
SDIO_SendCommand(&SDIO_CmdInitStructure);

/* 无响应命令：等 CMDSENT 而不是 CMDREND */
while (SDIO_GetFlagStatus(SDIO_FLAG_CMDSENT) == RESET) { }
SDIO_ClearFlag(SDIO_FLAG_CMDSENT);

/* ---- CMD8：查询是否支持 2.7~3.6V，短响应 ---- */
SDIO_CmdInitStructure.SDIO_Argument = 0x1AA;
SDIO_CmdInitStructure.SDIO_CmdIndex = 8;
SDIO_CmdInitStructure.SDIO_Response = SDIO_Response_Short;
SDIO_SendCommand(&SDIO_CmdInitStructure);
while (SDIO_GetFlagStatus(SDIO_FLAG_CMDREND) == RESET)
{
  if (SDIO_GetFlagStatus(SDIO_FLAG_CTIMEOUT) != RESET)
  {
    SDIO_ClearFlag(SDIO_FLAG_CTIMEOUT);   /* v1.x 卡会超时，属正常 */
    break;
  }
}

/* ---- ACMD41：必须先用 CMD55 前缀 ---- */
SDIO_CmdInitStructure.SDIO_Argument = 0x00;
SDIO_CmdInitStructure.SDIO_CmdIndex = 55;
SDIO_CmdInitStructure.SDIO_Response = SDIO_Response_Short;
SDIO_SendCommand(&SDIO_CmdInitStructure);
while (SDIO_GetFlagStatus(SDIO_FLAG_CMDREND) == RESET) { }
SDIO_ClearFlag(SDIO_FLAG_CMDREND);

SDIO_CmdInitStructure.SDIO_Argument = 0x40FF8000;
SDIO_CmdInitStructure.SDIO_CmdIndex = 41;
SDIO_SendCommand(&SDIO_CmdInitStructure);
/* 循环 CMD55+CMD41 直到 RESP1 的 bit31 为 1（卡就绪） */

SDIO_CmdInitTypeDef SDIO_CmdInitStructure;

SDIO_CmdStructInit(&SDIO_CmdInitStructure);   /* 先填默认值 */

/* 默认 CPSM 是 Disable、Response 是 No，这两个必须改 */
SDIO_CmdInitStructure.SDIO_Argument = 0x1AA;
SDIO_CmdInitStructure.SDIO_CmdIndex = 8;
SDIO_CmdInitStructure.SDIO_Response = SDIO_Response_Short;
SDIO_CmdInitStructure.SDIO_Wait     = SDIO_Wait_No;
SDIO_CmdInitStructure.SDIO_CPSM     = SDIO_CPSM_Enable;
SDIO_SendCommand(&SDIO_CmdInitStructure);

SDIO_CmdInitStructure.SDIO_CmdIndex  = 8;
SDIO_CmdInitStructure.SDIO_Response = SDIO_Response_Short;
SDIO_SendCommand(&SDIO_CmdInitStructure);

/* 等响应 */
while (SDIO_GetFlagStatus(SDIO_FLAG_CMDREND) == RESET) { }

/* 确认卡回应的确实是 CMD8 */
if (SDIO_GetCommandResponse() == 8)
{
  uint32_t r7 = SDIO_GetResponse(SDIO_RESP1);
}

/* ---- 短响应：CMD3 返回卡的 RCA ---- */
SDIO_CmdInitStructure.SDIO_CmdIndex  = 3;
SDIO_CmdInitStructure.SDIO_Response = SDIO_Response_Short;
SDIO_CmdInitStructure.SDIO_Argument = 0;
SDIO_SendCommand(&SDIO_CmdInitStructure);
while (SDIO_GetFlagStatus(SDIO_FLAG_CMDREND) == RESET) { }
uint32_t rca = SDIO_GetResponse(SDIO_RESP1) & 0xFFFF0000u;   /* 高 16 位是 RCA */

/* ---- 长响应：CMD9 读 CSD，四个寄存器都读 ---- */
SDIO_CmdInitStructure.SDIO_CmdIndex  = 9;
SDIO_CmdInitStructure.SDIO_Response = SDIO_Response_Long;
SDIO_CmdInitStructure.SDIO_Argument = rca;
SDIO_SendCommand(&SDIO_CmdInitStructure);
while (SDIO_GetFlagStatus(SDIO_FLAG_CMDREND) == RESET) { }

csd[0] = SDIO_GetResponse(SDIO_RESP1);
csd[1] = SDIO_GetResponse(SDIO_RESP2);
csd[2] = SDIO_GetResponse(SDIO_RESP3);
csd[3] = SDIO_GetResponse(SDIO_RESP4);

SDIO_DataInitTypeDef SDIO_DataInitStructure;
SDIO_CmdInitTypeDef  SDIO_CmdInitStructure;

/* ---- 第 1 步：配数据通路（必须在发命令之前） ---- */
SDIO_DataStructInit(&SDIO_DataInitStructure);
SDIO_DataInitStructure.SDIO_DataTimeOut   = 0xFFFFF;
SDIO_DataInitStructure.SDIO_DataLength    = 512;                       /* 1 块 × 512 字节 */
SDIO_DataInitStructure.SDIO_DataBlockSize = SDIO_DataBlockSize_512b;
SDIO_DataInitStructure.SDIO_TransferDir   = SDIO_TransferDir_ToSDIO;   /* 读卡方向 */
SDIO_DataInitStructure.SDIO_TransferMode  = SDIO_TransferMode_Block;
SDIO_DataInitStructure.SDIO_DPSM          = SDIO_DPSM_Enable;
SDIO_DataConfig(&SDIO_DataInitStructure);

/* ---- 第 2 步：发 CMD17 单块读 ---- */
SDIO_CmdStructInit(&SDIO_CmdInitStructure);
SDIO_CmdInitStructure.SDIO_Argument = addr;          /* 字节地址，SDHC 卡用块地址 */
SDIO_CmdInitStructure.SDIO_CmdIndex = 17;
SDIO_CmdInitStructure.SDIO_Response = SDIO_Response_Short;
SDIO_CmdInitStructure.SDIO_Wait     = SDIO_Wait_No;
SDIO_CmdInitStructure.SDIO_CPSM     = SDIO_CPSM_Enable;
SDIO_SendCommand(&SDIO_CmdInitStructure);

/* ---- 第 3 步：等响应并搬数据 ---- */
while (SDIO_GetFlagStatus(SDIO_FLAG_CMDREND) == RESET) { }
SDIO_ClearFlag(SDIO_FLAG_CMDREND);

for (uint32_t i = 0; i < 128; i++)      /* 512 字节 = 128 个 32 位字 */
{
  while (SDIO_GetFlagStatus(SDIO_FLAG_RXDAVL) == RESET) { }
  buf[i] = SDIO_ReadData();
}

while (SDIO_GetFlagStatus(SDIO_FLAG_DATAEND) == RESET) { }
SDIO_ClearFlag(SDIO_FLAG_DATAEND);

SDIO_DataInitTypeDef SDIO_DataInitStructure;

SDIO_DataStructInit(&SDIO_DataInitStructure);

/* 读一个 512 字节块 */
SDIO_DataInitStructure.SDIO_DataTimeOut   = 0xFFFFF;             /* 超时计数值，别设太小 */
SDIO_DataInitStructure.SDIO_DataLength    = 512;                 /* 必须改，默认是 0 */
SDIO_DataInitStructure.SDIO_DataBlockSize = SDIO_DataBlockSize_512b;
SDIO_DataInitStructure.SDIO_TransferDir   = SDIO_TransferDir_ToSDIO;  /* 读卡 */
SDIO_DataInitStructure.SDIO_TransferMode  = SDIO_TransferMode_Block;
SDIO_DataInitStructure.SDIO_DPSM          = SDIO_DPSM_Enable;    /* 必须改，默认是 Disable */
SDIO_DataConfig(&SDIO_DataInitStructure);

/* 启动一次 512 字节读 */
SDIO_DataConfig(&SDIO_DataInitStructure);
SDIO_SendCommand(&cmd17);

/* 边等边看还剩多少 */
while (SDIO_GetDataCounter() != 0)
{
  if (SDIO_GetFlagStatus(SDIO_FLAG_DTIMEOUT) != RESET) { break; }
}

if (SDIO_GetFlagStatus(SDIO_FLAG_DATAEND) != RESET)
{
  SDIO_ClearFlag(SDIO_FLAG_DATAEND);
}

/* 轮询读一个 512 字节块：buf 是 uint32_t 数组，长度 128 */
uint32_t i = 0;
while (i < 128)
{
  /* RXFIFOHF：FIFO 里至少有 8 个字 */
  if (SDIO_GetFlagStatus(SDIO_FLAG_RXFIFOHF) != RESET)
  {
    for (uint32_t k = 0; k < 8; k++)
    {
      buf[i++] = SDIO_ReadData();
    }
  }
}

/* 检查是否有错误 */
if (SDIO_GetFlagStatus(SDIO_FLAG_DCRCFAIL) != RESET) { /* CRC 错，数据不可信 */ }

/* 用 CPU 轮询写一个 512 字节块（buf 必须是 32 位对齐的数组） */
void SD_WriteBlockPolling(const uint32_t *buf, uint32_t words)
{
  for (uint32_t i = 0; i < words; i++)
  {
    /* 等 Tx FIFO 有空间：TXFIFOHE = 半空，可以继续塞 */
    while (FSMC_Wait_TxFifo() == 0) { }
    SDIO_WriteData(buf[i]);
  }

  /* 写完等 DATAEND / DBCKEND */
  while (SDIO_GetFlagStatus(SDIO_FLAG_DATAEND) == RESET) { }
  SDIO_ClearFlag(SDIO_FLAG_DATAEND);
}

/* 写方向：FIFOCNT 表示还能往 FIFO 里塞多少字 */
while (SDIO_GetFIFOCount() > 0 && written < words)
{
  SDIO_WriteData(buf[written++]);
}

/* 读方向：FIFOCNT 表示 FIFO 里已有多少字可读 */
while (SDIO_GetFIFOCount() > 0)
{
  buf[read++] = SDIO_ReadData();
}

/* 仅 SD I/O 卡需要 */
SDIO_SetSDIOOperation(ENABLE);
SDIO_SetSDIOReadWaitMode(SDIO_ReadWaitMode_DATA2);

/* 数据传输中临时暂停 */
SDIO_StartSDIOReadWait(ENABLE);
/* ... 处理急事 ... */
SDIO_StopSDIOReadWait(ENABLE);

/* 一定要停，否则传输会一直挂着直到超时 */

/* 与 Start 配对 */
SDIO_StartSDIOReadWait(ENABLE);
/* ... 暂停期间的处理 ... */
SDIO_StopSDIOReadWait(ENABLE);

/* 之后继续读 FIFO 拿剩下的数据 */

/* 驱动 SD I/O 卡（如 Wi-Fi SDIO 模块）时先开 SD I/O 模式 */
SDIO_SetSDIOOperation(ENABLE);

/* 4 位总线下用 DATA2 方式插入读等待 */
SDIO_SetSDIOReadWaitMode(SDIO_ReadWaitMode_DATA2);

SDIO_StartSDIOReadWait(ENABLE);
/* ... 处理数据 ... */
SDIO_StopSDIOReadWait(ENABLE);

/* 读普通 TF 卡：不要开！ */
/* SDIO_SetSDIOOperation(DISABLE); */

/* 接 SDIO Wi-Fi 模块：开启，并打开 SDIO 中断 */
SDIO_SetSDIOOperation(ENABLE);
SDIO_ITConfig(SDIO_IT_SDIOIT, ENABLE);   /* SD I/O 中断经 DAT1 上报 */

/* 仅 SD I/O 卡（如 Wi-Fi 模块）需要 */
SDIO_SetSDIOOperation(ENABLE);

/* 让下一条命令带上挂起标志 */
SDIO_SendSDIOSuspendCmd(ENABLE);

SDIO_CmdInitStructure.SDIO_CmdIndex = 52;
SDIO_CmdInitStructure.SDIO_Response = SDIO_Response_Short;
SDIO_SendCommand(&SDIO_CmdInitStructure);

/* 用完后关掉，避免影响后续普通命令 */
SDIO_SendSDIOSuspendCmd(DISABLE);

/* 普通 SD 卡：保持关闭即可，不用调用 */

/* CE-ATA 器件：使能命令完成信号并打开对应中断 */
SDIO_CommandCompletionCmd(ENABLE);
SDIO_CEATAITCmd(ENABLE);
SDIO_ITConfig(SDIO_IT_CEATAEND, ENABLE);

/* 仅 CE-ATA 器件需要 */
SDIO_CommandCompletionCmd(ENABLE);
SDIO_CEATAITCmd(ENABLE);
SDIO_ITConfig(SDIO_IT_CEATAEND, ENABLE);

/* 仅 CE-ATA 器件需要 */
SDIO_SetSDIOOperation(ENABLE);
SDIO_CommandCompletionCmd(ENABLE);
SDIO_CEATAITCmd(ENABLE);

SDIO_SendCEATACmd(ENABLE);   /* 发送 CMD61 */

/* 通用的「发命令 + 轮询等响应 + 超时保护」封装 */
uint32_t SD_SendCmdPolling(uint8_t idx, uint32_t arg, uint32_t resp, uint32_t timeout)
{
  SDIO_CmdInitTypeDef cmd;

  SDIO_CmdStructInit(&cmd);
  cmd.SDIO_Argument = arg;
  cmd.SDIO_CmdIndex = idx;
  cmd.SDIO_Response = resp;
  cmd.SDIO_Wait     = SDIO_Wait_No;
  cmd.SDIO_CPSM     = SDIO_CPSM_Enable;

  /* 发之前先清残留标志 */
  SDIO_ClearFlag(SDIO_FLAG_CMDREND | SDIO_FLAG_CMDSENT | SDIO_FLAG_CTIMEOUT | SDIO_FLAG_CCRCFAIL);
  SDIO_SendCommand(&cmd);

  while (timeout--)
  {
    if (SDIO_GetFlagStatus(SDIO_FLAG_CTIMEOUT) != RESET)
    {
      SDIO_ClearFlag(SDIO_FLAG_CTIMEOUT);
      return 1;   /* 超时 */
    }
    if (SDIO_GetFlagStatus(SDIO_FLAG_CCRCFAIL) != RESET)
    {
      SDIO_ClearFlag(SDIO_FLAG_CCRCFAIL);
      return 2;   /* CRC 错 */
    }
    if (resp == SDIO_Response_No)
    {
      if (SDIO_GetFlagStatus(SDIO_FLAG_CMDSENT) != RESET)
      {
        SDIO_ClearFlag(SDIO_FLAG_CMDSENT);
        return 0;
      }
    }
    else if (SDIO_GetFlagStatus(SDIO_FLAG_CMDREND) != RESET)
    {
      SDIO_ClearFlag(SDIO_FLAG_CMDREND);
      return 0;
    }
  }
  return 3;   /* 轮询次数耗尽 */
}

/* 发命令前清残留标志，避免误判本次结果 */
SDIO_ClearFlag(SDIO_FLAG_CMDREND | SDIO_FLAG_CMDSENT | SDIO_FLAG_CTIMEOUT | SDIO_FLAG_CCRCFAIL);

/* 数据传完后清数据标志和错误标志 */
SDIO_ClearFlag(SDIO_FLAG_DATAEND | SDIO_FLAG_DBCKEND | SDIO_FLAG_DCRCFAIL | SDIO_FLAG_DTIMEOUT | SDIO_FLAG_TXUNDERR | SDIO_FLAG_RXOVERR);

void SDIO_IRQHandler(void)
{
  /* 命令响应到了 */
  if (SDIO_GetITStatus(SDIO_IT_CMDREND) != RESET)
  {
    SDIO_ClearITPendingBit(SDIO_IT_CMDREND);
  }
  /* 数据传完了 */
  if (SDIO_GetITStatus(SDIO_IT_DATAEND) != RESET)
  {
    SDIO_ClearITPendingBit(SDIO_IT_DATAEND);
  }
  /* 出错 */
  if (SDIO_GetITStatus(SDIO_IT_CTIMEOUT) != RESET)
  {
    SDIO_ClearITPendingBit(SDIO_IT_CTIMEOUT);
  }
}

void SDIO_IRQHandler(void)
{
  if (SDIO_GetITStatus(SDIO_IT_DATAEND) != RESET)
  {
    /* 先处理业务再清位 */
    SD_TransferDone = 1;
    SDIO_ClearITPendingBit(SDIO_IT_DATAEND);
  }

  /* 或者一次清多个 */
  SDIO_ClearITPendingBit(SDIO_IT_DCRCFAIL | SDIO_IT_DTIMEOUT);
}
